PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS accounts(id TEXT PRIMARY KEY,username TEXT NOT NULL UNIQUE COLLATE NOCASE,name TEXT NOT NULL,password TEXT NOT NULL,salt TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,expires INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS sessions_user ON sessions(user_id);
CREATE TABLE IF NOT EXISTS comments(id TEXT PRIMARY KEY,title TEXT NOT NULL,user_id TEXT NOT NULL REFERENCES accounts(id),parent TEXT REFERENCES comments(id),body TEXT NOT NULL,spoiler INTEGER NOT NULL DEFAULT 0,created INTEGER NOT NULL,updated INTEGER,deleted INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS comments_title ON comments(title,parent,created DESC);
CREATE TABLE IF NOT EXISTS comment_votes(comment_id TEXT NOT NULL REFERENCES comments(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,value INTEGER NOT NULL CHECK(value IN(-1,1)),PRIMARY KEY(comment_id,user_id));
CREATE TABLE IF NOT EXISTS title_votes(title TEXT NOT NULL,user_id TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,value INTEGER NOT NULL CHECK(value IN(-1,1)),PRIMARY KEY(title,user_id));
CREATE TABLE IF NOT EXISTS library(user_id TEXT PRIMARY KEY REFERENCES accounts(id) ON DELETE CASCADE,data TEXT NOT NULL,updated INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS limits(key TEXT PRIMARY KEY,count INTEGER NOT NULL,expires INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS limits_expiry ON limits(expires);
CREATE INDEX IF NOT EXISTS sessions_expiry ON sessions(expires);
CREATE TABLE IF NOT EXISTS public_lists(id TEXT PRIMARY KEY,owner TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,local_id TEXT NOT NULL,name TEXT NOT NULL,items TEXT NOT NULL,created INTEGER NOT NULL,updated INTEGER NOT NULL,UNIQUE(owner,local_id));
CREATE INDEX IF NOT EXISTS public_lists_owner ON public_lists(owner);
